steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "statistics \u2014 Mathematical Statistics Functions \u2014 Python 3.12.3 documentation",
      "url": "https://docs.python.org/3/library/statistics.html",
      "snippet": "The Python standard library\u2019s statistics module includes mean(), pstdev(), and pvariance() for sample and population calculations. The docs note that pstdev() computes the population standard deviation and that coefficient of variation is commonly calculated as pstdev(data) / mean(data) * 100.",
      "domain": "docs.python.org",
      "rank": 1
    },
    {
      "title": "statistics \u2014 Mathematical statistics functions",
      "url": "https://docs.python.org/3/library/statistics.html#statistics.pstdev",
      "snippet": "Python 3.12 documentation explains that pstdev() returns the population standard deviation of sample data, using the population formula with denominator n rather than n-1. The mean() function is also defined in the same module, making it a standard reference for calculating coefficients of variation from mean and standard deviation.",
      "domain": "docs.python.org",
      "rank": 2
    },
    {
      "title": "How to Calculate the Coefficient of Variation in Python",
      "url": "https://www.geeksforgeeks.org/python/coefficient-of-variation-in-python/",
      "snippet": "This guide shows the coefficient of variation formula as CV = (standard deviation / mean) \u00d7 100, and demonstrates it in Python using statistics.mean() and statistics.pstdev(). For example, a dataset with mean 50 and population standard deviation 5 gives a CV of 10%.",
      "domain": "geeksforgeeks.org",
      "rank": 3
    },
    {
      "title": "Population Standard Deviation in Python | statistics.pstdev()",
      "url": "https://www.simplilearn.com/tutorials/python-tutorial/python-population-standard-deviation",
      "snippet": "Simplilearn\u2019s Python tutorial explains that population standard deviation uses every value in the dataset and divides by N, not N-1. It pairs pstdev() with mean() and shows how a coefficient of variation can be computed as the ratio of those two values, often multiplied by 100.",
      "domain": "simplilearn.com",
      "rank": 4
    },
    {
      "title": "Coefficient of Variation Formula and Examples",
      "url": "https://www.investopedia.com/terms/c/coefficientofvariation.asp",
      "snippet": "Investopedia defines the coefficient of variation as the ratio of the standard deviation to the mean, expressed as a percentage by multiplying by 100. The article gives the formula as CV = \u03c3 / \u03bc and notes that it is especially useful for comparing the relative variability of data sets with different units or means.",
      "domain": "investopedia.com",
      "rank": 5
    }
  ],
  "query": "Python statistics mean population standard deviation coefficient of variation formula",
  "count": 5
}

