  "results": [
    {
      "title": "Attention Is All You Need",
      "url": "https://arxiv.org/abs/1706.03762",
      "snippet": "Ashish Vaswani, Noam Shazeer, Niki Parmar, Jakob Uszkoreit, Llion Jones, Aidan N. Gomez, \u0141ukasz Kaiser and Illia Polosukhin introduced the Transformer in this 2017 paper. The abstract notes that their model relies entirely on attention mechanisms and achieved state-of-the-art results on WMT 2014 English-to-German and English-to-French translation tasks.",
      "domain": "arxiv.org",
      "rank": 1
    },
    {
      "title": "Attention Is All You Need - Google Research",
      "url": "https://research.google/pubs/pub46264/",
      "snippet": "Published in 2017, this landmark paper from Google researchers describes the Transformer architecture and its use of self-attention to replace recurrence and convolutions. The paper has been cited tens of thousands of times and is widely credited with enabling modern large language models.",
      "domain": "research.google",
      "rank": 2
    },
    {
      "title": "The Illustrated Transformer",
      "url": "https://jalammar.github.io/illustrated-transformer/",
      "snippet": "Jay Alammar\u2019s explainer breaks down the 2017 Transformer paper by Vaswani et al. and shows how attention heads, positional encoding, and encoder-decoder layers work. It is frequently linked by readers searching for the original paper and the authors\u2019 names.",
      "domain": "jalammar.github.io",
      "rank": 3
    },
    {
      "title": "Transformer models and self-attention mechanism explained",
      "url": "https://www.ibm.com/topics/transformers",
      "snippet": "IBM\u2019s overview explains how the Transformer architecture, first described in 2017 by Vaswani and colleagues, uses self-attention to process sequences in parallel. The article references the model\u2019s impact on BERT, GPT and other NLP systems introduced between 2018 and 2020.",
      "domain": "ibm.com",
      "rank": 4
    },
    {
      "title": "A Survey of Transformer Models and Their Variants",
      "url": "https://link.springer.com/article/10.1007/s10462-020-09845-2",
      "snippet": "This 2020 survey reviews the original Transformer paper by Vaswani et al. and later attention-based variants such as BERT, GPT-2 and XLNet. It summarizes how the 2017 architecture became the basis for many highly cited papers in 2018\u20132020.",
      "domain": "link.springer.com",
      "rank": 5
    }
  ],
  "query": "highly cited 2017 2020 transformer attention mechanisms paper authors title citation transformer attention",
  "count": 5
}

steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "Attention Is All You Need",
      "url": "https://arxiv.org/abs/1706.03762",
      "snippet": "The original Transformer paper by Ashish Vaswani, Noam Shazeer, Niki Parmar, Jakob Uszkoreit, and colleagues was published on arXiv in June 2017. It introduced self-attention and multi-head attention for sequence modeling and has become one of the most cited papers in modern NLP.",
      "domain": "arxiv.org",
      "rank": 1
    },
    {
      "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding",
      "url": "https://arxiv.org/abs/1810.04805",
      "snippet": "Jacob Devlin, Ming-Wei Chang, Kenton Lee, and Kristina Toutanova released BERT in October 2018, building on the Transformer architecture from 2017. The paper\u2019s bidirectional self-attention approach helped set new benchmarks on GLUE and SQuAD and is widely cited in NLP research.",
      "domain": "arxiv.org",
      "rank": 2
    },
    {
      "title": "Transformer-XL: Attentive Language Models Beyond a Fixed-Length Context",
      "url": "https://arxiv.org/abs/1901.02860",
      "snippet": "Published by Zihang Dai, Zhilin Yang, Yiming Yang, Jaime Carbonell, Quoc V. Le, and Ruslan Salakhutdinov in 2019, Transformer-XL extended self-attention with recurrence. The model improved long-range dependency handling on language modeling benchmarks such as WikiText-103.",
      "domain": "arxiv.org",
      "rank": 3
    },
    {
      "title": "XLNet: Generalized Autoregressive Pretraining for Language Understanding",
      "url": "https://arxiv.org/abs/1906.08237",
      "snippet": "Zhilin Yang, Zihang Dai, Yiming Yang, Jaime Carbonell, Ruslan Salakhutdinov, and Quoc V. Le introduced XLNet in June 2019. The paper combines autoregressive training with Transformer-XL ideas and reported strong results on 20 tasks including GLUE, SQuAD, and RACE.",
      "domain": "arxiv.org",
      "rank": 4
    },
    {
      "title": "An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale",
      "url": "https://arxiv.org/abs/2010.11929",
      "snippet": "Published in October 2020 by Alexey Dosovitskiy, Lucas Beyer, Alexander Kolesnikov, Dirk Weissenborn, Xiaohua Zhai, and others, this paper applied Transformer attention to image classification. The Vision Transformer (ViT) showed that a pure self-attention model could compete with CNNs on large-scale datasets such as ImageNet.",
      "domain": "arxiv.org",
      "rank": 5
    }
  ],
  "query": "site:arxiv.org transformer attention paper 2017 2020 highly cited self-attention authors",
  "count": 5
}

