[asy]

pair R,P,Q,SS;

SS = (-2,0);

P = (0,0);

Q = (2,0);

R = rotate(aSin(7/25))*(1.5,0);

dot("$S$",SS,S);

dot("$Q$",Q,S);

dot("$R$",R,N);

dot("$P$",P,S);

draw(Q--SS);

draw(P--R);

[/asy]

