  "results": [
    {
      "title": "Probability of at Least One 6 in 4 Rolls of a Fair Die",
      "url": "https://www.mathsisfun.com/data/probability-events-independent.html",
      "snippet": "For a fair six-sided die, the probability of not rolling a 6 on one roll is 5/6, so over 4 independent rolls it is (5/6)^4 = 625/1296 \u2248 0.4823. The complement, at least one 6, is 1 - (5/6)^4 = 671/1296 \u2248 0.5177.",
      "domain": "mathsisfun.com",
      "rank": 1
    },
    {
      "title": "Binomial Probability: At Least One Success",
      "url": "https://stattrek.com/probability-distributions/binomial.aspx",
      "snippet": "Using the complement rule, P(X\u22651) = 1 - P(X=0). For 4 trials with success probability p = 1/6, the probability of at least one success is 1 - (5/6)^4 = 0.5177469136, which can also be written as 671/1296.",
      "domain": "stattrek.com",
      "rank": 2
    },
    {
      "title": "Probability of At Least One Six in Four Die Rolls",
      "url": "https://www.onlinemathlearning.com/probability-dice-rolls.html",
      "snippet": "A common dice question is to find the chance of getting at least one 6 in 4 rolls. Since each roll is independent, the probability is 1 minus the probability of no 6s: 1 - (5/6)^4 = 671/1296, about 51.8%.",
      "domain": "onlinemathlearning.com",
      "rank": 3
    },
    {
      "title": "Complement Rule in Probability Examples",
      "url": "https://www.khanacademy.org/math/statistics-probability/probability-library/probability-rules/v/complement-rule",
      "snippet": "If the event is \u201crolling a 6,\u201d then the complement on one roll is 5/6. Khan Academy explains that for independent events you multiply the complement probabilities, so four rolls gives (5/6)^4 and the desired probability is 1 - (5/6)^4.",
      "domain": "khanacademy.org",
      "rank": 4
    },
    {
      "title": "Dice Probability Calculator: At Least One Six",
      "url": "https://www.calculatorsoup.com/calculators/discretemathematics/dice-probability.php",
      "snippet": "For 4 rolls of a fair die, the calculator shows the probability of at least one 6 is 0.5177469136. The exact fraction is 671/1296, derived from subtracting the no-six case, (5/6)^4 = 625/1296, from 1.",
      "domain": "calculatorsoup.com",
      "rank": 5
    }
  ],
  "query": "1 - (5/6)^4 exact probability at least one 6 in 4 rolls fair die",
  "count": 5
}

