steps.content:
[tool: web_search] {
  "results": [
    {
      "title": "Python Monte Carlo Simulation for Dice Rolls",
      "url": "https://realpython.com/python-monte-carlo-simulation/",
      "snippet": "Learn how to use Python to run Monte Carlo simulations with random sampling, including estimating probabilities from 1,000,000 trials. The tutorial demonstrates fair-die examples and shows how repeating 4 rolls can be used to approximate the chance of getting at least one 6.",
      "domain": "realpython.com",
      "rank": 1
    },
    {
      "title": "Probability of at Least One Six in Four Die Rolls",
      "url": "https://www.statology.org/probability-at-least-one-six-four-rolls/",
      "snippet": "A worked example computes the probability of rolling at least one 6 in 4 rolls of a fair six-sided die as 1 - (5/6)^4 = 51.8%. The article also includes a simple Python simulation using 1,000,000 trials to verify the theoretical result.",
      "domain": "statology.org",
      "rank": 2
    },
    {
      "title": "Monte Carlo simulation in Python with random.choice and random.randint",
      "url": "https://www.geeksforgeeks.org/monte-carlo-simulation-in-python/",
      "snippet": "This guide explains how to simulate repeated random events in Python, including dice rolls and estimating probabilities over 1,000,000 iterations. Example code uses the random module to model fair six-sided dice and compare simulated results with exact probability formulas.",
      "domain": "geeksforgeeks.org",
      "rank": 3
    },
    {
      "title": "Probability Lessons: At Least One Success in Repeated Trials",
      "url": "https://www.khanacademy.org/math/statistics-probability/probability-library/probability-rules/v/probability-of-at-least-one-event",
      "snippet": "Khan Academy shows that the probability of at least one success in repeated independent trials is found by subtracting the probability of no successes from 1. For a fair die rolled 4 times, the no-6 probability is (5/6)^4, which gives a result a little above 0.51.",
      "domain": "khanacademy.org",
      "rank": 4
    },
    {
      "title": "How to simulate dice rolls in Python using NumPy",
      "url": "https://numpy.org/doc/stable/reference/random/generated/numpy.random.Generator.choice.html",
      "snippet": "NumPy\u2019s random number generator can be used to simulate large batches of fair die rolls efficiently, including 1,000,000-trial experiments for estimating event probabilities. The documentation shows how to draw repeated samples from a finite set such as {1, 2, 3, 4, 5, 6} with reproducible seeds.",
      "domain": "numpy.org",
      "rank": 5
    }
  ],
  "query": "Python simulate probability at least one 6 in 4 rolls fair die 1 million trials",
  "count": 5
}

